tool_calls.arguments:
{"command":"kubectl exec -n egress app -- sh -c '
echo "--- HTTP through svc dep (no head) ---";
sh -c 'echo -n -e "GET / HTTP/1.1\r\nHost: dep.egress.svc.cluster.local\r\nConnection: close\r\n\r\n"; cat < /dev/tcp/10.96.185.101/80; head -10; echo "RC=$?";
echo "--- response body delivered (write to file) ---";
printf "svc-body-check\n" | sh -c 'exec 3<>/dev/tcp/10.96.185.101/80; printf "svc-body-check\n" >&3; cat <&3 | head -1; cat <&3; echo "rc=$?"'
echo "exit=$?"'
echo "--- dep pod replicas ---"; kubectl get pods -n egress dep -o jsonpath='{range .items[*]}{.metadata.name}{" s="}{.status.containerStatuses[0].ready}{"\n"}{end}'
echo "--- policy state ---"; kubectl get netpol -n egress default-deny-egress"}

